	@Test
	void sharedBrowserPrefixFixturesPreserveRdfSemantics() throws Exception {
		try (var input = getClass().getResourceAsStream("config-reference-prefix-cases.json")) {
			assertThat(input).isNotNull();
			for (JsonNode fixture : new ObjectMapper().readTree(input)) {
				String source = fixture.path("source").asText();
				String added = fixture.path("added").asText();
				String augmented = source.startsWith("\uFEFF")
						? "\uFEFF" + added + source.substring(1)
						: added + source;
				Model original = Rio.parse(new ByteArrayInputStream(source.getBytes(StandardCharsets.UTF_8)),
						"https://example.org/", RDFFormat.TURTLE);
				Model edited = Rio.parse(new ByteArrayInputStream(augmented.getBytes(StandardCharsets.UTF_8)),
						"https://example.org/", RDFFormat.TURTLE);
				assertThat(Models.isomorphic(original, edited)).as(fixture.path("name").asText()).isTrue();
				Model example = Rio.parse(new ByteArrayInputStream((source + fixture.path("fragment").asText())
						.getBytes(StandardCharsets.UTF_8)),
						"https://example.org/", RDFFormat.TURTLE);
				Model compact = Rio.parse(new ByteArrayInputStream((augmented + fixture.path("compact").asText())
						.getBytes(StandardCharsets.UTF_8)),
						"https://example.org/", RDFFormat.TURTLE);
				assertThat(Models.isomorphic(example, compact)).as(fixture.path("name").asText()).isTrue();
			}
		}
	}

	@Test
	void referenceWalksRepositoryWrappersAndNestedSailLayers() {
		MemoryStoreConfig memory = new MemoryStoreConfig();
		SchemaCachingRDFSInferencerConfig inferencer = new SchemaCachingRDFSInferencerConfig(memory);
		ContextAwareConfig wrapper = new ContextAwareConfig();
		wrapper.setDelegate(new SailRepositoryConfig(inferencer));

		ConfigReference reference = ConfigReference.describe(new RepositoryConfig("nested", wrapper));

		assertThat(reference.groups()).extracting(ConfigReference.Group::type)
				.containsExactly(
						"tag:rdf4j.org,2023:config/Repository", "openrdf:ContextAwareRepository",
						"openrdf:SailRepository",
						"rdf4j:SchemaCachingRDFSInferencer", "openrdf:MemoryStore");
		assertThat(reference.groups()).allMatch(ConfigReference.Group::complete);
		assertThat(reference.groups()).extracting(ConfigReference.Group::id).doesNotHaveDuplicates();
		assertThat(reference.groups().getLast().options()).extracting(ConfigReference.Option::predicate)
				.contains("tag:rdf4j.org,2023:config/mem.syncDelay",
						"tag:rdf4j.org,2023:config/sail.iterationCacheSyncThreshold");
	}

	@Test
	void metadataComesFromDeclarationsWithoutEvaluatingGetters() {
		ConfigReference.Group group = sailGroup(new MarkedConfig());

		assertThat(group.complete()).isTrue();
		assertThat(group.description()).isEqualTo("Test extension with complete metadata");
		List<ConfigReference.Option> own = group.options()
				.stream()
				.filter(option -> option.predicate().startsWith("urn:test:"))
				.toList();
		assertThat(own).hasSize(4);
		ConfigReference.Option overridden = own.stream()
				.filter(option -> option.predicate().equals("urn:test:option") && option.path().isEmpty())
				.findFirst()
				.orElseThrow();
		assertThat(overridden.description()).isEqualTo("Child documentation wins");
		assertThat(overridden.examples()).containsExactly("23");
		assertThat(overridden.aliases()).containsExactly("urn:test:legacy");
		assertThat(overridden.required()).isTrue();
		assertThat(overridden.datatype()).isEqualTo("http://www.w3.org/2001/XMLSchema#integer");
		ConfigReference.Option family = own.stream()
				.filter(option -> option.predicate().equals("urn:test:parameter:"))
				.findFirst()
				.orElseThrow();
		assertThat(family.parameterFamily()).isTrue();
		assertThat(family.multiple()).isTrue();
		assertThat(family.path()).containsExactly("urn:test:settings");
	}

