	@Test
	void luceneAndElasticsearchReferencesRespectBackendParameterApplicability() {
		ConfigReference.Group lucene = sailGroup(new LuceneSailConfig());
		ConfigReference.Group elasticsearch = sailGroup(new ElasticsearchSailConfig());
		List<String> common = List.of("indexDir", "reindexQuery", "indexedfields", "indexedtypes", "indexedlang",
				"indexBacktraceMode", "defaultNumDocs", "maxDocuments", "wktFields", "indexid", "incompletequeryfail",
				"evaluationMode").stream().map(key -> "tag:rdf4j.org,2023:config/lucene." + key).toList();
		List<String> luceneOnly = List.of("lucenedir", "useramdir", "transactional", "fsyncInterval", "similarity",
				"fuzzyPrefixLength").stream().map(key -> "tag:rdf4j.org,2023:config/lucene." + key).toList();
		assertThat(lucene.options()).extracting(ConfigReference.Option::predicate)
				.containsAll(common)
				.containsAll(luceneOnly);
		assertThat(elasticsearch.options()).extracting(ConfigReference.Option::predicate)
				.containsAll(common)
				.doesNotContainAnyElementsOf(luceneOnly);
		for (String key : List.of("analyzer", "queryAnalyzer")) {
			List<ConfigReference.Option> analyzers = elasticsearch.options()
					.stream()
					.filter(option -> option.predicate().equals("tag:rdf4j.org,2023:config/lucene." + key)
							|| option.examplePredicate().equals("tag:rdf4j.org,2023:config/lucene." + key))
					.toList();
			assertThat(analyzers).isNotEmpty();
			for (ConfigReference.Option analyzer : analyzers) {
				assertThat(analyzer.examples()).as("Elasticsearch %s uses analyzer names", key)
						.contains("\"standard\"")
						.noneMatch(example -> example.contains("org.apache.lucene."));
			}
		}
	}

