	@Test
	void registeredBuiltInConfigurationMetadataHasParseableIllustrativeObjects() throws Exception {
		List<ConfigReference.Group> groups = new ArrayList<>(
				ConfigReference.describe(new RepositoryConfig("catalog")).groups());
		RepositoryRegistry.getInstance()
				.getAll()
				.forEach(factory -> groups.addAll(
						ConfigReference.describe(new RepositoryConfig("catalog", factory.getConfig())).groups()));
		SailRegistry.getInstance()
				.getAll()
				.forEach(factory -> groups.addAll(ConfigReference.describe(
						new RepositoryConfig("catalog", new SailRepositoryConfig(factory.getConfig()))).groups()));

		assertThat(groups).isNotEmpty().allMatch(ConfigReference.Group::complete);
		for (ConfigReference.Group group : groups) {
			assertThat(group.description()).as("Description for %s", group.className()).isNotBlank();
			for (ConfigReference.Option option : group.options()) {
				assertThat(option.description()).as("%s %s", group.className(), option.predicate()).isNotBlank();
				assertThat(option.examples()).as("Examples for %s %s", group.className(), option.predicate())
						.isNotEmpty();
				String predicate = option.parameterFamily() ? option.examplePredicate() : option.predicate();
				assertThat(predicate).as("Concrete predicate for %s", option.predicate()).isNotBlank();
				if (option.parameterFamily()) {
					assertThat(predicate).startsWith(option.predicate());
				}
				for (String example : option.examples()) {
					String body = "<" + predicate + "> " + example;
					for (String path : option.path().reversed()) {
						body = "<" + path + "> [ " + body + " ]";
					}
					Model parsed = Rio.parse(new StringReader("[] " + body + " ."), "urn:example:", RDFFormat.TURTLE);
					Value value = parsed.filter(null, SimpleValueFactory.getInstance().createIRI(predicate), null)
							.objects()
							.stream()
							.findFirst()
							.orElseThrow();
					Class<? extends Value> valueClass = switch (option.valueType()) {
					case "literal" -> Literal.class;
					case "iri" -> IRI.class;
					case "resource", "list", "RDF list" -> Resource.class;
					default -> throw new AssertionError("Unknown RDF value type: " + option.valueType());
					};
					assertThat(value).as("Parsed %s example for %s", group.className(), option.predicate())
							.isInstanceOf(valueClass);
					if (value instanceof Literal literal && !option.datatype().isBlank()) {
						assertThat(literal.getDatatype().stringValue())
								.as("Example datatype for %s %s", group.className(), option.predicate())
								.isEqualTo(option.datatype());
					}
				}
			}
		}
	}

	@Test
	void everyPredicateReadByRegisteredConfigurationParsersIsDeclared() throws IOException {
		List<String> undeclared = new ArrayList<>();
		RepositoryConfig repository = new RepositoryConfig();
		undeclared.addAll(undeclaredReads(repository, "repository", null, null,
				(model, node) -> repository.parse(model, node)));
		for (RepositoryFactory factory : RepositoryRegistry.getInstance().getAll()) {
			RepositoryImplConfig configuration = factory.getConfig();
			undeclared.addAll(undeclaredReads(new RepositoryConfig("catalog", configuration),
					"repository/implementation", CONFIG.Rep.type, factory.getRepositoryType(),
					(model, node) -> configuration.parse(model, node)));
		}
		for (SailFactory factory : SailRegistry.getInstance().getAll()) {
			SailImplConfig configuration = factory.getConfig();
			undeclared.addAll(undeclaredReads(new RepositoryConfig("catalog", new SailRepositoryConfig(configuration)),
					"repository/implementation/sail", CONFIG.Sail.type, factory.getSailType(),
					(model, node) -> configuration.parse(model, node)));
		}

		assertThat(undeclared).as("Predicates read by parse() without a @ConfigProperty declaration").isEmpty();
	}

	private static List<String> undeclaredReads(RepositoryConfig envelope, String groupId, IRI typePredicate,
			String type, BiConsumer<Model, Resource> parser) throws IOException {
		ConfigReference.Group group = ConfigReference.describe(envelope)
				.groups()
				.stream()
				.filter(candidate -> candidate.id().equals(groupId))
				.findFirst()
				.orElseThrow();
		Resource node = SimpleValueFactory.getInstance().createIRI("urn:test:configuration");
		ReadRecordingModel model = new ReadRecordingModel();
		Set<String> declared = new HashSet<>();
		List<String> families = new ArrayList<>();
		for (ConfigReference.Option option : group.options()) {
			if (!option.path().isEmpty()) {
				continue;
			}
			List<String> names = new ArrayList<>(option.aliases());
			names.add(option.predicate());
			(option.parameterFamily() ? families : declared).addAll(names);
			boolean typeOption = typePredicate != null && option.predicate().equals(typePredicate.stringValue());
			if (option.required() && !option.parameterFamily() && !typeOption) {
				model.addAll(Rio.parse(new StringReader("<" + node.stringValue() + "> <" + option.predicate() + "> "
						+ option.examples().getFirst() + " ."), "urn:example:", RDFFormat.TURTLE));
			}
		}
		if (typePredicate != null) {
			model.add(node, typePredicate, SimpleValueFactory.getInstance().createLiteral(type));
		}

		parser.accept(model, node);

		return model.readPredicates(node)
				.stream()
				.map(IRI::stringValue)
				.filter(predicate -> !declared.contains(predicate))
				.filter(predicate -> families.stream().noneMatch(predicate::startsWith))
				.map(predicate -> group.className() + " reads " + predicate)
				.toList();
	}

	private static ConfigReference.Group sailGroup(AbstractSailImplConfig configuration) {
		return ConfigReference.describe(new RepositoryConfig("test", new SailRepositoryConfig(configuration)))
				.groups()
				.getLast();
	}

