	/** Records which predicates a parser looks up for each subject, without changing what the lookups return. */
	private static final class ReadRecordingModel extends LinkedHashModel {

		private static final long serialVersionUID = 1L;

		private final Map<Resource, Set<IRI>> reads = new HashMap<>();

		Set<IRI> readPredicates(Resource subject) {
			return reads.getOrDefault(subject, Set.of());
		}

		@Override
		public Model filter(Resource subj, IRI pred, Value obj, Resource... contexts) {
			record(subj, pred);
			return super.filter(subj, pred, obj, contexts);
		}

		@Override
		public Iterable<Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			record(subject, predicate);
			return super.getStatements(subject, predicate, object, contexts);
		}

		@Override
		public boolean contains(Resource subj, IRI pred, Value obj, Resource... contexts) {
			record(subj, pred);
			return super.contains(subj, pred, obj, contexts);
		}

		private void record(Resource subject, IRI predicate) {
			if (subject != null && predicate != null) {
				reads.computeIfAbsent(subject, ignored -> new LinkedHashSet<>()).add(predicate);
			}
		}
	}

	private static final class SharedRepositoryConfig extends SailRepositoryConfig
			implements DelegatingRepositoryImplConfig {
		private final RepositoryImplConfig delegate;

		SharedRepositoryConfig(SailImplConfig sail, RepositoryImplConfig delegate) {
			super(sail);
			this.delegate = delegate;
		}

		@Override
		public RepositoryImplConfig getDelegate() {
			return delegate;
		}
	}
